// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    Recorder rec;

    function setUp() public {
        c = new SimpleWallet();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, address(this).balance == 0 ? 1 : address(this).balance);
        vm.deal(address(this), type(uint256).max / 2);
        vm.deal(address(c), amount);
        vm.prank(c.owner());
        c.sendMoney(address(rec), amount);
        assertTrue(rec.lastValue() == amount);
    }
}

contract Recorder {
    uint256 public lastValue;
    receive() external payable {
        lastValue = msg.value;
    }
}
